    <Modal title="Approve Video" titleColor="#16A34A" maxWidth={480} onClose={onClose}
      bodyStyle={{ textAlign: 'center', padding: '24px 28px' }}
      footer={<div style={{ display: 'flex', justifyContent: 'center', gap: 10, width: '100%' }}>
